  "qualidade": {
    "t034": {
      "naturalidade": 86,
      "clareza": 90,
      "adequacao": 89,
      "correcao": 78,
      "critico": false,
      "justificativa": "Cumpre extensão, título, três parágrafos e citações literais; explica bem os limites. Acrescenta, sem base, envio à equipe técnica, disparo por subida rápida e ausência de definição pública do fluxo. Há alguma repetição sobre a falta de comparação."
    },
    "t035": {
      "naturalidade": 86,
      "clareza": 87,
      "adequacao": 84,
      "correcao": 65,
      "critico": false,
      "justificativa": "Texto fluido, no formato e na extensão pedidos, com números e declarações preservados. Entretanto, inventa central, intervalos de leitura, limites de disparo e equipe de plantão, além de atribuir ao mecanismo identificação de risco de alagamento não demonstrada na base."
    },
    "t036": {
      "naturalidade": 81,
      "clareza": 89,
      "adequacao": 85,
      "correcao": 66,
      "critico": false,
      "justificativa": "Organiza claramente funcionamento e limites, preservando dados, ressalvas e citações no formato solicitado. Afirma sem respaldo monitoramento contínuo, transmissão para central municipal, patamar de disparo e permanência da estrutura durante o piloto. Também trata a dúvida operacional como comprovadamente não respondida."
    },
    "t037": {
      "naturalidade": 80,
      "clareza": 83,
      "adequacao": 80,
      "correcao": 43,
      "critico": true,
      "justificativa": "Cumpre formato, extensão e citações, com boa explicação da ausência de comparação. Porém, fabrica o resultado de que a água subiu nos oito pontos durante as duas chuvas. Acrescenta leitura contínua, limites locais, envio à prefeitura e substituição de checagem manual; o título ainda sugere avaliação em andamento não informada."
    }
  }
}

